1	import { createHash } from "node:crypto";
2	import { mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
3	import { dirname, join, relative, sep } from "node:path";
4	import type { BlobMeta } from "./storage.js";
5	
6	const REQUEST_TIMEOUT_MS = 30_000;
7	
8	/**
9	 * Bookkeeping file sync keeps at the root of `dir` to remember the last
10	 * known common (synced) state per key, across separate CLI invocations.
11	 * Excluded from the local file walk so it's never itself treated as a file
12	 * to sync.
13	 */
14	const MANIFEST_FILENAME = ".syncbox-manifest.json";
15	
16	export interface SyncResult {
17	  uploaded: string[];
18	  downloaded: string[];
19	  unchanged: string[];
20	}
21	
22	type Manifest = Record<string, { sha256: string }>;
23	
24	interface LocalEntry {
25	  sha256: string;
26	  mtimeMs: number;
27	  content: Buffer;
28	}
29	
30	interface RemoteEntry {
31	  sha256: string;
32	  modified_at: string;
33	}
34	
35	/**
36	 * Bidirectionally syncs `dir` with the server by key and SHA-256. A file
37	 * present, or changed, on only one side is transferred to the other
38	 * (upload/download by content, same as push/pull). A file changed on both
39	 * sides since the last synced state recorded in `.syncbox-manifest.json` is
40	 * a conflict: the version with the newer modified_at/mtime wins, ties go to
41	 * the local version. With no recorded common state (first sync, or a key
42	 * neither side has seen synced before), a divergence is resolved the same
43	 * way there being no distinct "one side only" classification to make.
44	 * Never deletes on either side — a file missing on one side because it was
45	 * deleted there reappears from the other, since sync only ever transfers
46	 * content, it doesn't mirror deletions.
47	 */
48	export async function sync(dir: string, server: string): Promise<SyncResult> {
49	  const [manifest, localFiles, remoteBlobs] = await Promise.all([
50	    readManifest(dir),
51	    walkFiles(dir),
52	    fetchBlobList(server),
53	  ]);
54	
55	  const localByKey = new Map<string, LocalEntry>();
56	  for (const { key, path } of localFiles) {
57	    const [content, stats] = await Promise.all([readFile(path), stat(path)]);
58	    localByKey.set(key, {
59	      sha256: createHash("sha256").update(content).digest("hex"),
60	      mtimeMs: stats.mtimeMs,
61	      content,
62	    });
63	  }
64	  const remoteByKey = new Map<string, RemoteEntry>(
65	    remoteBlobs.map((b) => [b.key, { sha256: b.sha256, modified_at: b.modified_at }]),
66	  );
67	
68	  const uploaded: string[] = [];
69	  const downloaded: string[] = [];
70	  const unchanged: string[] = [];
71	  const newManifest: Manifest = {};
72	
73	  const allKeys = new Set([...localByKey.keys(), ...remoteByKey.keys()]);
74	  for (const key of allKeys) {
75	    const local = localByKey.get(key);
76	    const remote = remoteByKey.get(key);
77	
78	    if (local && !remote) {
79	      await uploadBlob(server, key, local.content);
80	      uploaded.push(key);
81	      newManifest[key] = { sha256: local.sha256 };
82	      continue;
83	    }
84	
85	    if (!local && remote) {
86	      const content = await downloadBlob(server, key);
87	      await writeLocalFile(dir, key, content);
88	      downloaded.push(key);
89	      newManifest[key] = { sha256: remote.sha256 };
90	      continue;
91	    }
92	
93	    const l = local as LocalEntry;
94	    const r = remote as RemoteEntry;
95	
96	    if (l.sha256 === r.sha256) {
97	      unchanged.push(key);
98	      newManifest[key] = { sha256: l.sha256 };
99	      continue;
100	    }
101	
102	    const winner = resolveConflict(l, r, manifest[key]?.sha256);
103	
104	    if (winner === "local") {
105	      await uploadBlob(server, key, l.content);
106	      uploaded.push(key);
107	      newManifest[key] = { sha256: l.sha256 };
108	    } else {
109	      const content = await downloadBlob(server, key);
110	      await writeLocalFile(dir, key, content);
111	      downloaded.push(key);
112	      newManifest[key] = { sha256: r.sha256 };
113	    }
114	  }
115	
116	  uploaded.sort();
117	  downloaded.sort();
118	  unchanged.sort();
119	
120	  await writeManifest(dir, newManifest);
121	
122	  return { uploaded, downloaded, unchanged };
123	}
124	
125	/**
126	 * Decides the winner for a key that differs between local and remote.
