      files.push(...(await walkFiles(root, fullPath)));
    } else if (entry.isFile()) {
      files.push({
        key: toPosixKey(relative(root, fullPath)),
        path: fullPath,
      });
    }
  }
  return files;
}

function toPosixKey(relativePath: string): string {
  return sep === "/" ? relativePath : relativePath.split(sep).join("/");
