      assert.deepEqual(result.uploaded.sort(), ["change.txt", "new.txt"]);
      assert.deepEqual(result.skipped, ["keep.txt"]);

      const blobs = await listBlobs(dataDir);
      assert.deepEqual(
        blobs.map((b) => b.key).sort(),
        ["change.txt", "keep.txt", "new.txt"],
      );
    });
  });
});

