1	import { createHash } from "node:crypto";
2	import { mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
3	import { dirname, join, relative, sep } from "node:path";
4	import {
5	  downloadBlob,
6	  fetchBlobList,
7	  uploadBlob,
8	  type FileFailure,
9	  type NetOptions,
10	} from "./net.js";
11	
12	/**
13	 * Bookkeeping file sync keeps at the root of `dir` to remember the last
14	 * known common (synced) state per key, across separate CLI invocations.
15	 * Excluded from the local file walk so it's never itself treated as a file
16	 * to sync.
17	 */
18	const MANIFEST_FILENAME = ".syncbox-manifest.json";
19	
20	export interface SyncResult {
21	  uploaded: string[];
22	  downloaded: string[];
23	  unchanged: string[];
24	  failed: FileFailure[];
25	}
26	
27	type Manifest = Record<string, { sha256: string }>;
28	
29	interface LocalEntry {
30	  sha256: string;
31	  mtimeMs: number;
32	  content: Buffer;
33	}
34	
35	interface RemoteEntry {
36	  sha256: string;
37	  modified_at: string;
38	}
39	
40	/**
41	 * Bidirectionally syncs `dir` with the server by key and SHA-256. A file
42	 * present, or changed, on only one side is transferred to the other
43	 * (upload/download by content, same as push/pull). A file changed on both
44	 * sides since the last synced state recorded in `.syncbox-manifest.json` is
45	 * a conflict: the version with the newer modified_at/mtime wins, ties go to
46	 * the local version. With no recorded common state (first sync, or a key
47	 * neither side has seen synced before), a divergence is resolved the same
48	 * way there being no distinct "one side only" classification to make.
49	 * Never deletes on either side — a file missing on one side because it was
50	 * deleted there reappears from the other, since sync only ever transfers
51	 * content, it doesn't mirror deletions.
52	 *
53	 * A key that fails - a local file that can't be read, or a network/server
